import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_node = 0
    best_score = -np.inf

    # Find index of current truck in all_truck_pos (assuming it exists)
    cur_idx = None
    for i, pos in enumerate(all_truck_pos):
        if np.allclose(np.array(pos), np.array(cur_truck_pos)):
            cur_idx = i
            break

    for idx, cust in enumerate(unvisited_customers):
        cust = np.array(cust)
        d_cur = np.linalg.norm(cust - np.array(cur_truck_pos))

        # Distances from all trucks to this customer, excluding the current truck
        other_dists = []
        for i, t in enumerate(all_truck_pos):
            if i != cur_idx:
                other_dists.append(np.linalg.norm(cust - np.array(t)))

        if len(other_dists) > 0:
            avg_other = np.mean(other_dists)
        else:
            avg_other = 0.0

        score = avg_other - d_cur
        if score > best_score:
            best_score = score
            best_node = idx

    return best_node

import numpy as np

def select_next_node(cur_truck_pos, depot_pos, all_truck_pos, unvisited_customers):
    best_node = None
    best_score = -np.inf
    cur = np.array(cur_truck_pos)
    other_trucks = [np.array(p) for p in all_truck_pos if not np.array_equal(p, cur_truck_pos)]
    for idx, cust in enumerate(unvisited_customers):
        cust = np.array(cust)
        d_cur = np.linalg.norm(cur - cust)
        if other_trucks:
            d_other_min = min(np.linalg.norm(cust - other) for other in other_trucks)
        else:
            d_other_min = 1e10  # large value to make ratio large when no other trucks
        score = (d_other_min + 1.0) / (d_cur + 1.0)
        if score > best_score:
            best_score = score
            best_node = idx
    if best_node is None:
        best_node = 0
    return best_node
